EXEC(N'CREATE PROCEDURE dbo.ReverseStockOperation
 @SourceOperationId uniqueidentifier, @ReversalOperationId uniqueidentifier, @PublicId char(24), @IdempotencyKey nvarchar(128), @OccurredAtUtc datetime2(7)
WITH EXECUTE AS OWNER
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @SourceOperationId IS NULL OR @ReversalOperationId IS NULL OR @SourceOperationId=@ReversalOperationId OR @IdempotencyKey IS NULL OR DATALENGTH(@IdempotencyKey)=0 OR DATALENGTH(@IdempotencyKey)>256 OR @PublicId LIKE ''%[^0-9a-f]%'' OR LEN(@PublicId)<>24 THROW 58795,N''Tham số hoàn tác không hợp lệ.'',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  IF NOT EXISTS(SELECT 1 FROM dbo.StockOperations WITH(UPDLOCK,HOLDLOCK) WHERE StockOperationId=@SourceOperationId AND OperationType<>N''Reversal'') THROW 58796,N''Operation nguồn không tồn tại hoặc không thể hoàn tác.'',1;
  IF EXISTS(SELECT 1 FROM dbo.StockOperations WITH(UPDLOCK,HOLDLOCK) WHERE ReversalOfOperationId=@SourceOperationId) THROW 58797,N''Operation nguồn đã được hoàn tác.'',1;
  IF NOT EXISTS(SELECT 1 FROM dbo.StockMovementLines WHERE StockOperationId=@SourceOperationId) THROW 58798,N''Operation nguồn không có dòng tồn kho.'',1;
  IF EXISTS(SELECT 1 FROM dbo.StockMovementLines l JOIN dbo.Stocks s WITH(UPDLOCK,HOLDLOCK) ON s.ProductVariantId=l.ProductVariantId JOIN dbo.ProductVariants v ON v.ProductVariantId=l.ProductVariantId JOIN dbo.Products p WITH(UPDLOCK,HOLDLOCK) ON p.ProductId=v.ProductId WHERE l.StockOperationId=@SourceOperationId AND (s.QuantityForSale-l.QuantityForSaleChange<0 OR s.QuantityInStorage-l.QuantityInStorageChange<0 OR (p.PurchaseCount IS NOT NULL AND p.PurchaseCount-l.PurchaseCountChange<0))) THROW 58799,N''Không đủ tồn kho hoặc lượt mua để hoàn tác.'',1;
  INSERT dbo.StockOperations(StockOperationId,PublicId,IdempotencyKey,OperationType,ReversalOfOperationId,OccurredAtUtc,Version) VALUES(@ReversalOperationId,@PublicId,@IdempotencyKey,N''Reversal'',@SourceOperationId,@OccurredAtUtc,0);
  INSERT dbo.StockMovementLines(StockMovementLineId,StockOperationId,ProductVariantId,QuantityForSaleChange,QuantityInStorageChange,PurchaseCountChange) SELECT NEWID(),@ReversalOperationId,ProductVariantId,-QuantityForSaleChange,-QuantityInStorageChange,-PurchaseCountChange FROM dbo.StockMovementLines WHERE StockOperationId=@SourceOperationId;
  UPDATE s SET QuantityForSale=s.QuantityForSale-l.QuantityForSaleChange, QuantityInStorage=s.QuantityInStorage-l.QuantityInStorageChange, UpdatedAtUtc=SYSUTCDATETIME() FROM dbo.Stocks s JOIN dbo.StockMovementLines l ON l.ProductVariantId=s.ProductVariantId WHERE l.StockOperationId=@SourceOperationId;
  UPDATE p SET PurchaseCount=CASE WHEN p.PurchaseCount IS NULL THEN NULL ELSE p.PurchaseCount-l.PurchaseCountChange END FROM dbo.Products p JOIN dbo.ProductVariants v ON v.ProductId=p.ProductId JOIN dbo.StockMovementLines l ON l.ProductVariantId=v.ProductVariantId WHERE l.StockOperationId=@SourceOperationId;
  COMMIT;
 END TRY
 BEGIN CATCH
  IF XACT_STATE()<>0 ROLLBACK;
  THROW;
 END CATCH;
END;');
GRANT EXECUTE ON dbo.ReverseStockOperation TO OperationalRuntime;
